const body = $input.first().json.body ?? $input.first().json;

function abort(reason, detail) {
  return [{
    json: {
      ok: false,
      reason,
      detail: detail || '',
      mode: '',
      pdf_bytes_est: 0,
      tenant_id: '',
      order_id: null,
      source: '',
      sent_to: '',
      secret_used: '',
      _abort: true,
    },
  }];
}

// Dual-secret rollout: WEBHOOK_SECRET (new) + optional WEBHOOK_SECRET_OLD.
// Response includes secret_used: "new"|"old" so ops can drop OLD when unused.
const secretNew = ($env.WEBHOOK_SECRET || '').toString();
const secretOld = ($env.WEBHOOK_SECRET_OLD || '').toString();
if (!secretNew) {
  return abort('missing_field', 'WEBHOOK_SECRET_env');
}

const webhookSecret = (body.webhook_secret ?? '').toString().trim();
if (!webhookSecret) {
  return abort('missing_field', 'webhook_secret');
}

let secret_used = '';
if (webhookSecret === secretNew) {
  secret_used = 'new';
} else if (secretOld && webhookSecret === secretOld) {
  secret_used = 'old';
} else {
  return abort('unauthorized', 'webhook_secret');
}

const phone = (body.customer_phone ?? '').toString().trim();
if (!phone) {
  return abort('missing_field', 'customer_phone');
}

// Instance naming (must match Evolution + Edge + Flutter):
//   evolutionInstanceNameForUser(userId) => shop_ + userId.replace(/-/g, '_')
// No tenant_ / shop_basra_1 / hardcoded fallbacks.
const instanceName = (body.instance_name ?? '').toString().trim();
if (!instanceName) {
  return abort('missing_field', 'instance_name');
}

let digits = phone.replace(/\D/g, '');
if (digits.startsWith('0')) digits = '964' + digits.slice(1);
else if (digits.length === 10 && digits.startsWith('7')) digits = '964' + digits;

const order = body.order ?? {};
const messageText = (body.message_text ?? '').toString().trim();
const pdfBase64 = (body.pdf_base64 ?? '').toString().trim();
const pdfFilename = (body.pdf_filename ?? 'oil_change_service.pdf').toString().trim();
const pdfMimetype = (body.pdf_mimetype ?? 'application/pdf').toString().trim();

return [{
  json: {
    _abort: false,
    secret_used,
    instanceName,
    phone: digits,
    order,
    tenant_id: (body.tenant_id ?? '').toString().trim(),
    order_id: body.order_id ?? null,
    message_text: messageText,
    pdf_base64: pdfBase64,
    pdf_filename: pdfFilename,
    pdf_mimetype: pdfMimetype,
  },
}];

const prev = $('Validate Payload').first().json;
if (prev._abort) {
  return [{ json: prev }];
}

const fromApp = (prev.message_text ?? '').toString().trim();
let text = fromApp;
let source = fromApp ? 'app' : 'fallback';

if (!text) {
  const o = prev.order || {};
  const name = o.customer_name ?? 'عميلنا الكريم';
  const store = o.store_name ?? 'المحل';
  text = `مرحباً ${name}، شكراً لزيارتكم ${store} لغيار الزيت.\n`;
  if (o.vehicle) text += `المركبة: ${o.vehicle}\n`;
  if (o.oil) text += `الزيت: ${o.oil}\n`;
  if (o.total_iqd) text += `الإجمالي: ${o.total_iqd} د.ع\n`;
  if (o.invoice_id) text += `رقم الفاتورة: ${o.invoice_id}\n`;
  text += 'نراكم عند موعد الصيانة القادمة.';
}

return [{
  json: {
    ...prev,
    message_text: text,
    source,
  },
}];

const prev = $input.first().json;
if (prev._abort) {
  return [{ json: prev }];
}

const instance = (prev.instanceName || '').toString().trim();
const evolutionBase = ($env.EVOLUTION_BASE_URL || 'http://naboo-evolution:8080').replace(/\/$/, '');
const apiKey = ($env.EVOLUTION_API_KEY || '').toString().trim();

function fail(reason, detail) {
  return [{
    json: {
      ok: false,
      reason,
      detail: detail || '',
      mode: '',
      pdf_bytes_est: 0,
      tenant_id: prev.tenant_id || '',
      order_id: prev.order_id ?? null,
      source: prev.source || '',
      sent_to: prev.phone || '',
      secret_used: prev.secret_used || '',
    },
  }];
}

if (!apiKey) return fail('missing_field', 'EVOLUTION_API_KEY_env');
if (!instance) return fail('missing_field', 'instance_name');

const fullText = (prev.message_text || '').toString();
if (!fullText.trim()) return fail('missing_field', 'message_text');

let phone = (prev.phone || '').toString().replace(/\D/g, '');
if (!phone) return fail('missing_field', 'phone');

// تأكيد أن الرقم على واتساب واستعمال الصيغة الرسمية (يتجنب @lid الميت).
try {
  const checked = await this.helpers.httpRequest({
    method: 'POST',
    url: `${evolutionBase}/chat/whatsappNumbers/${instance}`,
    headers: { apikey: apiKey, 'Content-Type': 'application/json' },
    body: { numbers: [phone] },
    json: true,
    timeout: 15000,
  });
  const info = Array.isArray(checked) ? checked[0] : null;
  if (!info || info.exists !== true) {
    return fail('invalid_phone', 'number_not_on_whatsapp');
  }
  if (info.number) phone = String(info.number).replace(/\D/g, '');
} catch (e) {
  // إن فشل التحقق نتابع بالإرسال — بعض النسخ لا تدعم المسار
}

let ok = false;
let reason = '';
let mode = 'text';
let detail = '';
let sentTo = phone;
let remoteJid = '';

try {
  const result = await this.helpers.httpRequest({
    method: 'POST',
    url: `${evolutionBase}/message/sendText/${instance}`,
    headers: { apikey: apiKey, 'Content-Type': 'application/json' },
    body: {
      number: phone,
      text: fullText,
      delay: 800,
      linkPreview: false,
    },
    json: true,
    timeout: 25000,
  });
  remoteJid = (result?.key?.remoteJid || '').toString();
  sentTo = phone;
  // @lid بدون بديل رقمي غالباً لا يصل للزبون
  if (remoteJid.includes('@lid') && !(result?.key?.remoteJidAlt)) {
    ok = false;
    reason = 'evolution_error';
    detail = `lid_without_phone_jid:${remoteJid}`;
  } else {
    ok = true;
  }
} catch (e) {
  detail = (e.message || String(e)).slice(0, 400);
  const msg = detail.toLowerCase();
  if (msg.includes('disconnect') || msg.includes('not connected') || msg.includes('closed')) {
    reason = 'whatsapp_disconnected';
  } else if (msg.includes('timeout') || msg.includes('timed out')) {
    reason = 'timeout';
  } else if (msg.includes('401') || msg.includes('403')) {
    reason = 'unauthorized';
  } else if (msg.includes('404')) {
    reason = 'instance_not_found';
  } else if (msg.includes('rate') || msg.includes('429')) {
    reason = 'rate_limited';
  } else if (msg.includes('exists') || msg.includes('not.*whatsapp') || msg.includes('400')) {
    reason = 'invalid_phone';
  } else {
    reason = 'evolution_error';
  }
}

return [{
  json: {
    ok,
    reason,
    mode,
    detail: detail || remoteJid,
    pdf_bytes_est: 0,
    tenant_id: prev.tenant_id,
    order_id: prev.order_id,
    source: prev.source,
    sent_to: sentTo,
    instanceName: instance,
    secret_used: prev.secret_used || '',
  },
}];
